function o(t=Date.now()){return new Date(t+18e6).toISOString().slice(0,10)}function r(t,n){const e=new Date(`${t}T00:00:00Z`);return e.setUTCDate(e.getUTCDate()+n),e.toISOString().slice(0,10)}function s(t){const n=new Date(`${t}T00:00:00+05:00`),e=new Date(n.getTime()+24*3600*1e3);return{from:n.toISOString(),to:e.toISOString()}}function i(t,n){return n!=="sold"?t:t.filter(e=>Number(e.sold)>0||Number(e.returned)>0)}export{s as d,i as r,r as s,o as t};
